// SetNameMACAndUpInterface is a helper function that will bind interface name and Mac
// and return a function that can run in the netns.Do() call for execution in a network namespace.
func SetNameMACAndUpInterface(l netlink.Link, endpt Endpoint) func(ns.NetNS) error {
	return func(_ ns.NetNS) error {
		// l was resolved in the namespace that created the link. Moving it to
		// another namespace keeps its name but changes its ifindex when that
		// index is taken there, and netlink addresses links by ifindex.
		// Resolve it again here so an unrelated interface is never changed.
		name := l.Attrs().Name
		link, err := netlink.LinkByName(name)
		if err != nil {
			return fmt.Errorf("failed to find link %q: %w", name, err)
		}
		l = link

		// rename the link created with random name if its length is acceptable by linux
		if IsValidInterfaceName(endpt.GetIfaceName()) {
			err := netlink.LinkSetName(l, endpt.GetIfaceName())
			if err != nil {
				return fmt.Errorf(
					"failed to rename link: %v", err)
			}
		} else {
			// when the name is too long, we add a sanitized interface name as AltName
			sanitizedIfaceName := clabutils.SanitizeInterfaceName(endpt.GetIfaceName())
			err := netlink.LinkAddAltName(l, sanitizedIfaceName)
			if err != nil {
				return fmt.Errorf(
					"failed to add altname: %v", err)
			}
		}

		// lets set the MAC address if provided
		if len(endpt.GetMac()) == 6 {
			err := netlink.LinkSetHardwareAddr(l, endpt.GetMac())
			if err != nil {
				return err
			}
		}

		if endpt.GetIfaceAlias() != "" {
			err := netlink.LinkSetAlias(l, endpt.GetIfaceAlias())
			if err != nil {
				return err
			}
			// Set a sanitized altname for ease of access. '/', and ' ' are changed to '-'
			sanitizedIfaceName := clabutils.SanitizeInterfaceName(endpt.GetIfaceAlias())
			err = netlink.LinkAddAltName(l, sanitizedIfaceName)
			if err != nil {
				return err
			}
		}

		if err := addOwnershipAltName(l, endpt); err != nil {
			return err
		}

		// bring the given link up
		if err := netlink.LinkSetUp(l); err != nil {
			return fmt.Errorf("failed to set %q up: %v",
				endpt.GetIfaceName(), err)
		}

		return nil
	}
}

func ownershipAltName(endpt Endpoint) string {
	return ownershipAltNameFor(ownershipName(endpt.GetNode()), endpt.GetIfaceName())
}

// ownershipName returns the logical owner name recorded in the ownership marker
// of node's interfaces. mgmt-net link nodes use a stable name rather than the
// bridge they resolve to, so the marker of a mgmt-net endpoint does not depend
// on the management network it attaches to.
func ownershipName(node Node) string {
	if _, ok := node.(*mgmtBridgeLinkNode); ok {
		return mgmtNetOwnerName
	}
	return node.GetShortName()
}

func ownershipAltNameFor(nodeName, ifaceName string) string {
	sum := sha1.Sum([]byte(nodeName + "\x00" + ifaceName))
	return ownershipAltNamePrefix + hex.EncodeToString(sum[:8])
}

func hasOwnershipAltName(link netlink.Link) bool {
	for _, altName := range link.Attrs().AltNames {
		if strings.HasPrefix(altName, ownershipAltNamePrefix) {
			return true
		}
	}

	return false
}

// HasOwnershipAltName reports whether link carries a containerlab ownership marker.
func HasOwnershipAltName(link netlink.Link) bool {
	return hasOwnershipAltName(link)
}

// HasOwnershipAltNameFor reports whether link is owned by the logical endpoint
// identified by nodeName and ifaceName.
func HasOwnershipAltNameFor(link netlink.Link, nodeName, ifaceName string) bool {
	if link == nil || nodeName == "" || ifaceName == "" {
		return false
	}

	want := ownershipAltNameFor(nodeName, ifaceName)
	for _, altName := range link.Attrs().AltNames {
		if altName == want {
			return true
		}
	}

	return false
}

func addOwnershipAltName(link netlink.Link, endpt Endpoint) error {
	if hasOwnershipAltName(link) {
		return nil
	}

	altName := ownershipAltName(endpt)
	if err := linkAddAltName(link, altName); err != nil {
		if isAltNameNotSupportedErr(err) {
			log.Warnf(
				"kernel does not support interface altname capability; consider upgrading the kernel for full containerlab compatibility. Continuing without containerlab ownership marker %q for %s",
				altName,
				endpt,
			)
			return nil
		}

		return fmt.Errorf("failed to add containerlab ownership altname: %w", err)
	}

	return nil
}

func isAltNameNotSupportedErr(err error) bool {
	return errors.Is(err, syscall.EOPNOTSUPP)
}

